using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides a web search tool that the agent can invoke to find information on a topic.
/// Uses the Google Custom Search JSON API when configured, otherwise falls back to
/// a simulated search for demonstration purposes.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly string? _apiKey;
    private readonly string? _searchEngineId;

    public WebSearchTool(HttpClient httpClient, string? apiKey = null, string? searchEngineId = null)
    {
        _httpClient = httpClient;
        _apiKey = apiKey;
        _searchEngineId = searchEngineId;
    }

    [Description("Searches the web for information on a given query. Returns a list of results with titles, snippets, and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        if (!string.IsNullOrEmpty(_apiKey) && !string.IsNullOrEmpty(_searchEngineId))
        {
            return await LiveSearchAsync(query, maxResults);
        }

        return SimulatedSearch(query, maxResults);
    }

    private async Task<string> LiveSearchAsync(string query, int maxResults)
    {
        var url = $"https://www.googleapis.com/customsearch/v1?key={_apiKey}&cx={_searchEngineId}&q={Uri.EscapeDataString(query)}&num={maxResults}";

        var response = await _httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();

        using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
        var results = new List<object>();

        if (doc.RootElement.TryGetProperty("items", out var items))
        {
            foreach (var item in items.EnumerateArray())
            {
                results.Add(new
                {
                    title = item.GetProperty("title").GetString(),
                    snippet = item.GetProperty("snippet").GetString(),
                    url = item.GetProperty("link").GetString(),
                });
            }
        }

        return results.Count > 0
            ? JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true })
            : "No results found.";
    }

    private static string SimulatedSearch(string query, int maxResults)
    {
        // Simulated results for demonstration when no API key is configured
        var simulatedResults = new List<object>
        {
            new
            {
                title = $"Overview of {query} - Wikipedia",
                snippet = $"{query} is a broad topic encompassing many areas of study. Recent developments have shown significant progress in both theoretical understanding and practical applications.",
                url = $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}"
            },
            new
            {
                title = $"Latest Research on {query} - ScienceDaily",
                snippet = $"Researchers have made breakthrough discoveries related to {query}, publishing findings in several peer-reviewed journals. Key areas include efficiency improvements and novel approaches.",
                url = $"https://www.sciencedaily.com/search/?keyword={Uri.EscapeDataString(query)}"
            },
            new
            {
                title = $"{query}: A Comprehensive Guide - TechReview",
                snippet = $"This guide covers the fundamentals of {query}, including history, current state-of-the-art, and future directions. Industry adoption has accelerated in recent years.",
                url = $"https://www.techreview.com/guide/{Uri.EscapeDataString(query)}"
            },
            new
            {
                title = $"The Impact of {query} on Industry - Forbes",
                snippet = $"Industry leaders discuss how {query} is transforming business processes. The global market is projected to grow significantly over the next decade.",
                url = $"https://www.forbes.com/topics/{Uri.EscapeDataString(query)}"
            },
            new
            {
                title = $"Understanding {query}: Expert Analysis - Nature",
                snippet = $"Expert analysis reveals that {query} continues to evolve rapidly. New methodologies and frameworks are being developed to address current limitations.",
                url = $"https://www.nature.com/search?q={Uri.EscapeDataString(query)}"
            },
        };

        var results = simulatedResults.Take(maxResults).ToList();
        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides a note-taking tool that the agent can use to record findings during research.
/// Notes are stored in-memory and can be retrieved to compile a final summary.
/// </summary>
public sealed class NoteTool
{
    private readonly List<NoteEntry> _notes = [];

    public IReadOnlyList<NoteEntry> Notes => _notes.AsReadOnly();

    [Description("Saves a research note with a topic label and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short label or category for the note (e.g., 'definition', 'key finding', 'statistic')")] string topic,
        [Description("The content of the note")] string content,
        [Description("The source URL or reference, if available")] string? source = null)
    {
        var entry = new NoteEntry
        {
            Id = _notes.Count + 1,
            Topic = topic,
            Content = content,
            Source = source,
            Timestamp = DateTime.UtcNow,
        };

        _notes.Add(entry);
        return $"Note #{entry.Id} saved under topic '{topic}'.";
    }

    [Description("Retrieves all saved research notes, optionally filtered by topic.")]
    public string GetNotes(
        [Description("Optional topic filter — only return notes matching this topic")] string? topic = null)
    {
        var filtered = string.IsNullOrEmpty(topic)
            ? _notes
            : _notes.Where(n => n.Topic.Contains(topic, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return topic is null
                ? "No notes have been saved yet."
                : $"No notes found for topic '{topic}'.";
        }

        return JsonSerializer.Serialize(filtered, new JsonSerializerOptions { WriteIndented = true });
    }

    [Description("Returns a count of all saved notes, grouped by topic.")]
    public string GetNoteSummary()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        var grouped = _notes.GroupBy(n => n.Topic, StringComparer.OrdinalIgnoreCase)
            .Select(g => new { topic = g.Key, count = g.Count() });

        return JsonSerializer.Serialize(new { totalNotes = _notes.Count, byTopic = grouped },
            new JsonSerializerOptions { WriteIndented = true });
    }

    /// <summary>
    /// Formats all collected notes into a readable research brief (used at the end of a session).
    /// </summary>
    public string FormatResearchBrief()
    {
        if (_notes.Count == 0)
            return "No notes were collected during this research session.";

        var sb = new StringBuilder();
        sb.AppendLine("═══════════════════════════════════════");
        sb.AppendLine("         RESEARCH NOTES COLLECTED       ");
        sb.AppendLine("═══════════════════════════════════════");

        foreach (var group in _notes.GroupBy(n => n.Topic, StringComparer.OrdinalIgnoreCase))
        {
            sb.AppendLine();
            sb.AppendLine($"  [{group.Key.ToUpperInvariant()}]");
            foreach (var note in group)
            {
                sb.AppendLine($"    • {note.Content}");
                if (!string.IsNullOrEmpty(note.Source))
                    sb.AppendLine($"      Source: {note.Source}");
            }
        }

        sb.AppendLine();
        sb.AppendLine("═══════════════════════════════════════");
        return sb.ToString();
    }
}

public sealed class NoteEntry
{
    public int Id { get; init; }
    public required string Topic { get; init; }
    public required string Content { get; init; }
    public string? Source { get; init; }
    public DateTime Timestamp { get; init; }
}

