using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides a note-taking tool that the agent can use to record findings during research.
/// Notes are stored in-memory and can be retrieved to compile a final summary.
/// </summary>
public sealed class NoteTool
{
    private readonly List<NoteEntry> _notes = [];

    public IReadOnlyList<NoteEntry> Notes => _notes.AsReadOnly();

    [Description("Saves a research note with a topic label and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short label or category for the note (e.g., 'definition', 'key finding', 'statistic')")] string topic,
        [Description("The content of the note")] string content,
        [Description("The source URL or reference, if available")] string? source = null)
    {
        var entry = new NoteEntry
        {
            Id = _notes.Count + 1,
            Topic = topic,
            Content = content,
            Source = source,
            Timestamp = DateTime.UtcNow,
        };

        _notes.Add(entry);
        return $"Note #{entry.Id} saved under topic '{topic}'.";
    }

    [Description("Retrieves all saved research notes, optionally filtered by topic.")]
    public string GetNotes(
        [Description("Optional topic filter — only return notes matching this topic")] string? topic = null)
    {
        var filtered = string.IsNullOrEmpty(topic)
            ? _notes
            : _notes.Where(n => n.Topic.Contains(topic, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return topic is null
                ? "No notes have been saved yet."
                : $"No notes found for topic '{topic}'.";
        }

        return JsonSerializer.Serialize(filtered, new JsonSerializerOptions { WriteIndented = true });
    }

    [Description("Returns a count of all saved notes, grouped by topic.")]
    public string GetNoteSummary()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        var grouped = _notes.GroupBy(n => n.Topic, StringComparer.OrdinalIgnoreCase)
            .Select(g => new { topic = g.Key, count = g.Count() });

        return JsonSerializer.Serialize(new { totalNotes = _notes.Count, byTopic = grouped },
            new JsonSerializerOptions { WriteIndented = true });
    }

    /// <summary>
    /// Formats all collected notes into a readable research brief (used at the end of a session).
    /// </summary>
    public string FormatResearchBrief()
    {
        if (_notes.Count == 0)
            return "No notes were collected during this research session.";

        var sb = new StringBuilder();
        sb.AppendLine("═══════════════════════════════════════");
        sb.AppendLine("         RESEARCH NOTES COLLECTED       ");
        sb.AppendLine("═══════════════════════════════════════");

        foreach (var group in _notes.GroupBy(n => n.Topic, StringComparer.OrdinalIgnoreCase))
        {
            sb.AppendLine();
            sb.AppendLine($"  [{group.Key.ToUpperInvariant()}]");
            foreach (var note in group)
            {
                sb.AppendLine($"    • {note.Content}");
                if (!string.IsNullOrEmpty(note.Source))
                    sb.AppendLine($"      Source: {note.Source}");
            }
        }

        sb.AppendLine();
        sb.AppendLine("═══════════════════════════════════════");
        return sb.ToString();
    }
}

public sealed class NoteEntry
{
    public int Id { get; init; }
    public required string Topic { get; init; }
    public required string Content { get; init; }
    public string? Source { get; init; }
    public DateTime Timestamp { get; init; }
}

