using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

// --- Configuration -----------------------------------------------------------
// Set OPENAI_API_KEY (or AI__ApiKey in appsettings) and optionally
// GOOGLE_SEARCH_API_KEY + GOOGLE_SEARCH_ENGINE_ID for live web search.
var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

// --- Services ----------------------------------------------------------------
builder.Services.AddHttpClient();

builder.Services.AddChatClient(b => b
    .UseLogging()
    .Use(new OpenAIClient(apiKey).GetChatClient(modelId)));

builder.Services.AddSingleton<NoteTool>();
builder.Services.AddSingleton(sp =>
{
    var httpFactory = sp.GetRequiredService<IHttpClientFactory>();
    return new WebSearchTool(
        httpFactory.CreateClient("WebSearch"),
        Environment.GetEnvironmentVariable("GOOGLE_SEARCH_API_KEY"),
        Environment.GetEnvironmentVariable("GOOGLE_SEARCH_ENGINE_ID"));
});

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var webSearch = host.Services.GetRequiredService<WebSearchTool>();
var noteTool = host.Services.GetRequiredService<NoteTool>();
var logger = host.Services.GetRequiredService<ILogger<Program>>();

// --- Tool registration -------------------------------------------------------
var tools = new AIToolCollection
{
    AIFunctionFactory.Create(webSearch.SearchWebAsync),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetNotes),
    AIFunctionFactory.Create(noteTool.GetNoteSummary),
};

// --- Agent interaction -------------------------------------------------------
Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine("       🔍 AI Research Agent 🔍        ");
Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine($"\nResearching: {topic}...\n");

    var systemPrompt = """
        You are a thorough research assistant. When given a topic:
        1. Search the web for information using the SearchWebAsync tool (make 2-3 searches with different query angles).
        2. For each useful finding, save a note using SaveNote with an appropriate topic label, the key information, and the source URL.
        3. After gathering enough information, call GetNotes to review what you've collected.
        4. Finally, produce a well-structured summary that synthesizes your findings, organized by theme. Include source references.

        Be concise but thorough. Focus on facts, recent developments, and expert perspectives.
        """;

    var chatHistory = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}"),
    };

    var options = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = tools,
        ToolMode = ChatToolMode.Auto,
